<script setup lang="ts">
import { nextTick, onBeforeUnmount, onMounted, ref } from 'vue'
import type { User } from '../types'
const props=defineProps<{currentUser:User}>(); const emit=defineEmits<{alert:[msg:string,type?:'success'|'error']}>()
const list=ref<any[]>([]), selected=ref<any>(null), messages=ref<any[]>([]), input=ref(''), loading=ref(false), end=ref<HTMLElement|null>(null); let timer:ReturnType<typeof setInterval>|null=null
async function api(url:string,opt?:RequestInit){const r=await fetch(url,opt);const d=await r.json().catch(()=>null);if(!r.ok)throw new Error(d?.message||`HTTP ${r.status}`);return d}
async function loadList(){try{list.value=await api('/api/customer-service/admin/conversations',{headers:{'X-Current-Role':props.currentUser.role}});if(!selected.value&&list.value[0])select(list.value[0])}catch(e:any){emit('alert','加载客服会话失败：'+(e?.message||e),'error')}}
async function select(item:any){selected.value=item;loading.value=true;try{const d=item.id?await api(`/api/customer-service/conversations/${item.id}?viewer=staff`,{headers:{'X-Current-Role':props.currentUser.role}}):await api('/api/customer-service/admin/conversations/open',{method:'POST',headers:{'Content-Type':'application/json','X-Current-Role':props.currentUser.role},body:JSON.stringify({userId:item.userId})});selected.value=d.conversation;messages.value=d.messages||[];await loadList();nextTick(()=>end.value?.scrollIntoView())}catch(e:any){emit('alert','读取会话失败：'+(e?.message||e),'error')}finally{loading.value=false}}
async function send(){const content=input.value.trim();if(!content||!selected.value)return;input.value='';try{const d=await api(`/api/customer-service/conversations/${selected.value.id}/messages`,{method:'POST',headers:{'Content-Type':'application/json','X-Current-Role':props.currentUser.role},body:JSON.stringify({currentUserId:props.currentUser.id,senderType:'staff',content})});messages.value=d.messages||[];await loadList();nextTick(()=>end.value?.scrollIntoView({behavior:'smooth'}))}catch(e:any){emit('alert','发送失败：'+(e?.message||e),'error')}}
async function toggleHandoff(){if(!selected.value)return;const enabled=!selected.value.humanTakeover;try{const d=await api(`/api/customer-service/conversations/${selected.value.id}/human-takeover`,{method:'POST',headers:{'Content-Type':'application/json','X-Current-Role':props.currentUser.role},body:JSON.stringify({enabled,currentUserId:props.currentUser.id})});selected.value=d.conversation;messages.value=d.messages||[];await loadList();emit('alert',enabled?'已转接人工客服，后续用户消息不再触发AI回复':'已恢复AI首响模式','success')}catch(e:any){emit('alert','切换失败：'+(e?.message||e),'error')}}
async function close(){if(!selected.value)return;try{await api(`/api/customer-service/conversations/${selected.value.id}/close`,{method:'POST',headers:{'X-Current-Role':props.currentUser.role}});emit('alert','会话已关闭','success');await loadList()}catch(e:any){emit('alert','操作失败：'+(e?.message||e),'error')}}
function key(e:KeyboardEvent){if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send()}}
onMounted(async()=>{await loadList();timer=setInterval(async()=>{await loadList();if(selected.value)select(selected.value)},12000)});onBeforeUnmount(()=>{if(timer)clearInterval(timer)})
</script>
<template><section class="service-desk"><header class="desk-head"><div><span>CUSTOMER CARE CONSOLE</span><h2>客服助手与人工会话</h2><p>AI 自动首响，人工客服可在此查看、回复和关闭 C 端用户会话。</p></div><button @click="loadList">刷新会话</button></header><div class="desk-body"><aside><div class="queue-title"><b>用户会话</b><em>{{ list.length }} 个</em></div><button v-for="item in list" :key="item.id" :class="{active:selected?.id===item.id}" @click="select(item)"><i>{{ item.userName?.slice(0,1)||'用' }}</i><div><b>{{ item.userName }}</b><small>{{ item.lastMessage||'等待消息' }}</small></div><em v-if="item.unreadCount">{{ item.unreadCount }}</em><span>{{ item.status==='new'?'暂未发起':item.status==='closed'?'已关闭':item.humanTakeover?'人工处理中':'AI 首响中' }}</span></button><p v-if="!list.length" class="empty">暂无 C 端用户</p></aside><main v-if="selected"><header><div><span>会话 #{{ selected.id }} · {{ selected.humanTakeover ? '人工客服已接入' : 'AI 首响模式' }}</span><b>{{ selected.userName }} 的咨询</b></div><div class="head-actions"><button class="handoff" @click="toggleHandoff">{{ selected.humanTakeover ? '恢复 AI 首响' : '接入人工客服' }}</button><button @click="close">关闭会话</button></div></header><div class="desk-messages"><div v-if="loading" class="empty">正在载入...</div><article v-for="m in messages" :key="m.id" :class="m.senderType"><i>{{ m.senderType==='user'?'用':m.senderType==='staff'?'人':'AI' }}</i><div><b>{{ m.senderType==='user'?selected.userName:m.senderType==='staff'?'人工客服':'AI 客服助手' }}</b><p>{{m.content}}</p><small>{{m.createdAt}}</small></div></article><div ref="end"/></div><footer><textarea v-model="input" rows="2" placeholder="以人工客服身份回复用户；Enter 发送，Shift + Enter 换行" @keydown="key"></textarea><button @click="send">发送回复</button></footer></main><main v-else class="blank"><b>请选择一个用户会话</b><span>用户从 C 端客服助手发来的消息会出现在这里。</span></main></div></section></template>
<style scoped>.service-desk{padding:26px;min-height:calc(100vh - 120px);background:linear-gradient(135deg,#f7faf9,#f5f1eb)}.desk-head{display:flex;justify-content:space-between;gap:20px;align-items:flex-end;margin-bottom:18px}.desk-head span,.desk-body main header span{display:block;color:#0f766e;font-size:10px;font-weight:900;letter-spacing:.12em}.desk-head h2{margin:5px 0;color:#173f3a;font-size:25px}.desk-head p{margin:0;color:#64748b;font-size:13px}.desk-head>button,.desk-body main header button,.desk-body footer button{border:0;border-radius:12px;padding:10px 13px;background:#0f766e;color:#fff;font:inherit;font-weight:800}.desk-body{display:grid;grid-template-columns:310px minmax(0,1fr);height:calc(100vh - 220px);min-height:540px;overflow:hidden;border:1px solid #d9e7e2;border-radius:22px;background:#fff;box-shadow:0 16px 46px rgba(41,63,55,.1)}.desk-body aside{overflow:auto;border-right:1px solid #e4ece9;background:#fcfffe}.queue-title{display:flex;justify-content:space-between;padding:16px;border-bottom:1px solid #e4ece9}.queue-title em{font-size:11px;color:#0f766e;font-style:normal}.desk-body aside>button{position:relative;display:grid;grid-template-columns:31px 1fr auto;gap:8px;width:100%;padding:13px;border:0;border-bottom:1px solid #edf2f0;background:transparent;text-align:left}.desk-body aside>button.active{background:#eaf9f5}.desk-body aside i{display:grid;place-items:center;width:29px;height:29px;border-radius:10px;background:#d9f1eb;color:#0f766e;font-style:normal;font-weight:900}.desk-body aside b{display:block;color:#253b36;font-size:13px}.desk-body aside small{display:block;overflow:hidden;margin-top:4px;color:#94a3b8;font-size:11px;text-overflow:ellipsis;white-space:nowrap}.desk-body aside em{display:grid;place-items:center;min-width:18px;height:18px;border-radius:99px;background:#ef4444;color:#fff;font-size:10px;font-style:normal}.desk-body aside span{grid-column:2/-1;color:#94a3b8;font-size:10px}.desk-body main{display:grid;grid-template-rows:auto 1fr auto;min-width:0}.desk-body main header{display:flex;justify-content:space-between;align-items:center;padding:15px 18px;border-bottom:1px solid #e5eeeb}.desk-body main header b{display:block;color:#1e3934;font-size:15px}.desk-body main header button{padding:7px 10px;background:#fff4ed;color:#c2410c;font-size:11px}.head-actions{display:flex;gap:7px}.desk-body main header button.handoff{background:#e8f8f4;color:#0f766e}.desk-messages{overflow:auto;padding:18px;background:linear-gradient(180deg,#fbfdfc,#f3faf8)}.desk-messages article{display:flex;gap:8px;max-width:76%;margin-bottom:13px}.desk-messages article.user{margin-left:auto;flex-direction:row-reverse}.desk-messages article>i{display:grid;place-items:center;width:28px;height:28px;border-radius:9px;background:#d9f1eb;color:#0f766e;font-size:10px;font-style:normal;font-weight:900}.desk-messages article.staff>i{background:#fef3c7;color:#92400e}.desk-messages article>div{padding:9px 11px;border:1px solid #e0eae6;border-radius:5px 14px 14px;background:#fff}.desk-messages article.user>div{border:0;border-radius:14px 5px 14px 14px;background:#0f766e;color:#fff}.desk-messages b{font-size:10px}.desk-messages p{margin:4px 0;white-space:pre-wrap;font-size:13px;line-height:1.55}.desk-messages small{font-size:9px;color:#94a3b8}.desk-messages article.user small{color:#ccfbf1}.desk-body footer{display:flex;gap:10px;padding:12px;border-top:1px solid #e4ece9}.desk-body footer textarea{flex:1;resize:none;border:1px solid #cfe1dc;border-radius:12px;padding:9px;font:12px inherit}.empty{padding:25px;text-align:center;color:#94a3b8;font-size:12px}.blank{place-items:center;align-content:center;background:#f8fbfa;color:#64748b}.blank b{color:#25423c}.blank span{margin-top:6px;font-size:12px}@media(max-width:800px){.service-desk{padding:14px}.desk-body{grid-template-columns:1fr;height:auto}.desk-body aside{max-height:210px;border-right:0;border-bottom:1px solid #e4ece9}.desk-body main{min-height:520px}.desk-head{align-items:flex-start;flex-direction:column}}</style>
